<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Accessor\PlatformIdentityVersionAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the PlatformIdentityVersionAccessor trait.
 *
 * Covers null default, string/VO assignment via withVersion,
 * getVersion/version accessors, and isVersionChanged with/without original.
 */
class PlatformIdentityVersionAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withVersion creates a new instance with the Version set
     * from a string value, and getVersion returns the primitive string.
     */
    public function testWithVersionFromString(): void
    {
        // Arrange
        $holder = new ImplWithPlatformIdentityVersionAccessorUnitTest();

        // Act
        $result = $holder->withVersion(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getVersion());
    }
    /**
     * Asserts that withversion has access to the value object
     * from a string value, and getVersion returns the primitive string.
     */
    public function testWithVersionFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithPlatformIdentityVersionAccessorUnitTest();

        // Act
        $result = $holder->withVersion(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->version()->value());
    }
    public function testChangedVersion(): void
    {
        // Arrange
        $holder = new ImplWithPlatformIdentityVersionAccessorUnitTest();
        $original = $holder->withVersion(1);
        $same = $holder->withVersion(1);
        $modified = $holder->withVersion(2);

        // Act
        $unchanged = $holder->isVersionChanged();
        $withSame = $original->isVersionChanged($same);
        $withDiferent = $original->isVersionChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithPlatformIdentityVersionAccessorUnitTest
{
    use PlatformIdentityVersionAccessor;
}
